diagnosticModules.recommendedFix:
# Nginx Googlebot Log Isolation
log_format googlebot '$remote_addr - [$time_local] "$request" $status $body_bytes_sent "$http_user_agent" $request_time';
map $http_user_agent $is_googlebot {
    default 0;
    "~*(Googlebot|Google-InspectionTool)" 1;
}

# Nginx 301 Permanent Redirect Mapping
location = /old-legacy-path {
    return 301 https://example.com;
}
location /old-category/ {
    return 301 /new-category/;
}
